import DOFValues from "./DOFValues";
import AbstractLayer from './AbstractLayer';

/**
 * Represents a background.
 * @class Background
 * @extends jibo.face.AbstractLayer
 * @memberof jibo.face
 * @param {Boolean} cache Cache the texture.
 */
class Background extends AbstractLayer {

    /**
     * The base sprite for holding the texture.
     * @name jibo.face.Background#sprite
     * @type {PIXI.Sprite}
     */
    public sprite:PIXI.Sprite;

    /**
     * Default eye texture when nothing is set.
     * @method jibo.face.Background#init
     * @param {PIXI.Texture} texture The default texture to use
     */
    init(texture:PIXI.Texture):void {
        this.sprite = new PIXI.Sprite(texture);
        this.addChild(this.sprite);
        super.init(texture);
    }

    /**
     * Update of DOFValues.
     * @method jibo.face.Background#display
     * @param {Array<Number>} timestamp Timestamp when update is called.
     * @param {jibo.face.DOFValues} dofValues Update display according to these values.
     */
    display(timestamp:number[], dofValues:DOFValues):boolean {

        if (!super.display(timestamp, dofValues)) {
            return false;
        }
        this.texturePath = dofValues.screenBGTextureInfixBn_r;
        this.sprite.tint = this.rgb2hex(
            dofValues.screenBG_redChannelBn_r,
            dofValues.screenBG_greenChannelBn_r,
            dofValues.screenBG_blueChannelBn_r
        );
        return true;
    }

    /**
     * Override destroy
     * @method jibo.face.Background#destroy
     * @override
     */
    destroy(): void {
        super.destroy();
        this.sprite = null;
    }

    /**
     * Set current eye texture.
     * @method jibo.face.Background#setTexture
     * @protected
     * @param {PIXI.Texture} texture Texture to set
     */
    protected setTexture(texture:PIXI.Texture): void {
        super.setTexture(texture);
        if (texture && texture.baseTexture) {
            this.sprite.texture = texture;
        }
        else {
            this.reset(false);
        }
    }
}

export default Background;
